  FxModelPolicy.validate(payload);JSONObject p=body.getJSONObject("parameters");for(String number:new String[]{"width","height","steps","n_samples","seed"}){Object raw=p.opt(number);if(!(raw instanceof Number)||!Double.isFinite(((Number)raw).doubleValue())||((Number)raw).doubleValue()!=Math.floor(((Number)raw).doubleValue()))throw new FxRuntime.ApiError(400,"invalid_parameters","整数参数格式无效");}int w=p.getInt("width"),h=p.getInt("height"),count=p.optInt("n_samples",1);if(w<64||h<64||w>4096||h>4096||w%64!=0||h%64!=0||count<1||count>8||p.getDouble("steps")<1||p.getDouble("scale")<0)throw new FxRuntime.ApiError(400,"invalid_parameters","图像参数无效");long seed=p.getLong("seed");if(seed<0||seed>4294967295L)throw new FxRuntime.ApiError(400,"invalid_seed","随机种子尚未解析");
