 void consumeFrame(String frame,Map<Integer,byte[]> finals,JSONObject job)throws Exception{String event="",data="";for(String line:frame.split("\n")){if(line.startsWith("event:"))event=line.substring(6).trim();if(line.startsWith("data:"))data+=line.substring(5).trim();}if(data.isEmpty()||data.equals("[DONE]"))return;JSONObject value=new JSONObject(data);String type=value.optString("type",event);if(type.equals("error")||value.has("error"))throw new IOException("上游图像流返回错误");List<byte[]> images=new ArrayList<>();collect(value,images);if(type.equals("final")){int index=value.optInt("samp_ix",0);for(int i=0;i<images.size();i++)finals.put(index+i,images.get(i));}else if(value.has("image")&&value.optString("image").length()<4*1024*1024){synchronized(lock){job.put("preview","data:image/jpeg;base64,"+value.optString("image"));job.put("streamEvents",job.optInt("streamEvents")+1);}}}
 static void collect(Object value,List<byte[]> out)throws Exception{if(value instanceof JSONObject){JSONObject o=(JSONObject)value;for(String key:new String[]{"b64_json","image"})if(o.opt(key) instanceof String){String s=o.getString(key);if(s.startsWith("data:"))s=s.substring(s.indexOf(',')+1);try{byte[] bytes=Base64.decode(s,Base64.DEFAULT);imageType(bytes);out.add(bytes);}catch(Exception ignored){}}for(String key:new String[]{"data","images","output"})if(o.has(key))collect(o.get(key),out);}else if(value instanceof JSONArray){JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++)collect(a.get(i),out);}}
 static String imageType(byte[] b)throws IOException{if(b.length>8&&b[0]==(byte)137&&b[1]=='P')return "image/png";if(b.length>2&&b[0]==(byte)255&&b[1]==(byte)216)return "image/jpeg";if(b.length>12&&new String(b,0,4,StandardCharsets.US_ASCII).equals("RIFF"))return "image/webp";if(b.length>6&&new String(b,0,3,StandardCharsets.US_ASCII).equals("GIF"))return "image/gif";if(b.length>16&&new String(b,4,4,StandardCharsets.US_ASCII).equals("ftyp")&&Arrays.asList("avif","avis").contains(new String(b,8,4,StandardCharsets.US_ASCII)))return "image/avif";throw new IOException("图片格式无效");}
 static Object clean(Object value,String token)throws Exception{if(value instanceof JSONObject){JSONObject result=new JSONObject(),source=(JSONObject)value;Iterator<String> keys=source.keys();while(keys.hasNext()){String key=keys.next();if(key.matches("(?i)^(source|mask|image|images|reference_image.*|director_reference_images|controlnet_condition|encoded|encoding|encodings|dataURL|b64_json|authorization|api[_-]?key|access[_-]?token|refresh[_-]?token|password|secret|cookie|headers)$"))continue;result.put(key,clean(source.get(key),token));}return result;}if(value instanceof JSONArray){JSONArray out=new JSONArray(),a=(JSONArray)value;for(int i=0;i<a.length();i++)out.put(clean(a.get(i),token));return out;}if(value instanceof String)return ((String)value).replace(token,"[redacted]").replaceAll("(?i)Bearer\\s+[A-Za-z0-9._~+/=-]+","Bearer [redacted]");return value;}
 static byte[] metadata(byte[] b,JSONObject recipe)throws Exception{if(!imageType(b).equals("image/png"))return b;ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(b,0,8);int at=8;while(at+12<=b.length){int len=ByteBuffer.wrap(b,at,4).getInt();if(len<0||at+len+12>b.length)throw new IOException("PNG 数据不完整");String type=new String(b,at+4,4,StandardCharsets.US_ASCII);if(type.equals("IEND")){byte[] json=recipe.toString().getBytes(StandardCharsets.UTF_8),prefix="novelai_studio\0\0\0\0\0".getBytes(StandardCharsets.US_ASCII);if(json.length>2*1024*1024)throw new IOException("参数元数据过大");ByteArrayOutputStream payload=new ByteArrayOutputStream();payload.write(prefix);payload.write(json);byte[] data=payload.toByteArray(),name="iTXt".getBytes(StandardCharsets.US_ASCII);out.write(ByteBuffer.allocate(4).putInt(data.length).array());out.write(name);out.write(data);CRC32 crc=new CRC32();crc.update(name);crc.update(data);out.write(ByteBuffer.allocate(4).putInt((int)crc.getValue()).array());}out.write(b,at,len+12);at+=len+12;}return out.toByteArray();}
 static byte[] privateSharingImage(byte[] bytes)throws Exception{
 android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<1||options.outHeight<1||(long)options.outWidth*options.outHeight>32000000)throw new IOException("图片超过安全导出尺寸");
 android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null)throw new IOException("图片无法读取");android.graphics.Bitmap clean=bitmap.copy(android.graphics.Bitmap.Config.ARGB_8888,true);bitmap.recycle();try{int[] row=new int[clean.getWidth()];for(int y=0;y<clean.getHeight();y++){clean.getPixels(row,0,row.length,0,y,row.length,1);for(int x=0;x<row.length;x++){int a=row[x]>>>24;if(a>0)a|=1;row[x]=(a<<24)|(row[x]&0x00fefefe);}clean.setPixels(row,0,row.length,0,y,row.length,1);}ByteArrayOutputStream out=new ByteArrayOutputStream();if(!clean.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out))throw new IOException("PNG 导出失败");return out.toByteArray();}finally{clean.recycle();}
 }
 static byte[] stripMetadata(byte[] b)throws Exception{String mime=imageType(b);if(mime.equals("image/png")){ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(b,0,8);int at=8;while(at+12<=b.length){int len=ByteBuffer.wrap(b,at,4).getInt();if(len<0||at+len+12>b.length)throw new IOException("PNG 数据不完整");String type=new String(b,at+4,4,StandardCharsets.US_ASCII);if(!Arrays.asList("tEXt","zTXt","iTXt","eXIf").contains(type))out.write(b,at,len+12);at+=len+12;}return out.toByteArray();}if(mime.equals("image/jpeg")){ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(b,0,2);int at=2;while(at+4<=b.length){int marker=b[at+1]&255;if(marker==218||marker==217){out.write(b,at,b.length-at);break;}int len=((b[at+2]&255)<<8)|(b[at+3]&255);if(len<2||at+len+2>b.length)throw new IOException("JPEG 数据不完整");if(marker!=225&&marker!=237&&marker!=254)out.write(b,at,len+2);at+=len+2;}return out.toByteArray();}if(mime.equals("image/webp")){ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(b,0,12);int at=12;while(at+8<=b.length){String type=new String(b,at,4,StandardCharsets.US_ASCII);int len=ByteBuffer.wrap(b,at+4,4).order(ByteOrder.LITTLE_ENDIAN).getInt(),size=8+len+(len&1);if(len<0||at+size>b.length)throw new IOException("WebP 数据不完整");if(!type.equals("EXIF")&&!type.equals("XMP ")){byte[] chunk=Arrays.copyOfRange(b,at,at+size);if(type.equals("VP8X"))chunk[8]&=~12;out.write(chunk);}at+=size;}byte[] result=out.toByteArray();ByteBuffer.wrap(result,4,4).order(ByteOrder.LITTLE_ENDIAN).putInt(result.length-8);return result;}throw new IOException("此图片格式暂不支持去参数导出");}
